            make(90, "Al-Balad", 10, "وَهَدَيْنَاهُ النَّجْدَيْنِ", "وَهَدَيْنَاهُ <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّ</ghunnah><qalqalah>جْ</qalqalah>دَيْنِ", "Wa hadaynahun-najdayn", "And have shown him the two ways?", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(90, "Al-Balad", 11, "فَلَا اقْتَحَمَ الْعَقَبَةَ", "فَلَا <hamzat_wasl>ا</hamzat_wasl><tafkhim>قْ</tafkhim><qalqalah>تَحَمَ</qalqalah> <hamzat_wasl>الْ</hamzat_wasl>عَ<tafkhim>قَبَةَ</tafkhim>", "Falaqtahamal-'aqabah", "But he has not broken through the difficult pass.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(90, "Al-Balad", 12, "وَمَا أَدْرَاكَ مَا الْعَقَبَةُ", "وَمَا <madd>أَ</madd><qalqalah>دْرَاكَ</qalqalah> مَا <hamzat_wasl>الْ</hamzat_wasl>عَ<tafkhim>قَبَةُ</tafkhim>", "Wa ma adraka mal-'aqabah", "And what can make you know what is [breaking through] the difficult pass?", listOf(TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(90, "Al-Balad", 13, "فَكُّ رَقَبَةٍ", "فَكُّ رَ<tafkhim>قَبَةٍ</tafkhim>", "Fakku raqabah", "It is the freeing of a slave", listOf(TajweedRuleType.TAFKHIM)),
            make(90, "Al-Balad", 14, "أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ", "أَوْ <madd>إِ</madd><tafkhim>طْ</tafkhim><qalqalah>عَامٌ</qalqalah> فِي يَوْمٍ <ikhfa>ذِي</ikhfa> مَسْغَبَةٍ", "Aw it'amun fi yawmin dhi masghabah", "Or feeding on a day of severe hunger", listOf(TajweedRuleType.MADD, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.GHUNNAH)),
            make(90, "Al-Balad", 15, "يَتِيمًا ذَا مَقْرَبَةٍ", "يَتِيمًا <ikhfa>ذَا</ikhfa> مَ<qalqalah>قْ</qalqalah>رَبَةٍ", "Yatimang dha maqrabah", "An orphan of near relationship", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(90, "Al-Balad", 16, "أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ", "أَوْ مِسْكِينًا <ikhfa>ذَا</ikhfa> مَتْرَبَةٍ", "Aw miskinang dha matrabah", "Or a needy person in misery", listOf(TajweedRuleType.GHUNNAH)),
            make(90, "Al-Balad", 17, "ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِ", "<ghunnah>ثُمَّ</ghunnah> كَانَ مِنَ <hamzat_wasl>الَّذِينَ</hamzat_wasl> <madd>آمَنُوا</madd> وَتَوَاصَوْا بِ<hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّ</tafkhim><qalqalah>بْ</qalqalah>رِ وَتَوَاصَوْا بِ<hamzat_wasl>الْ</hamzat_wasl>مَرْحَمَةِ", "Thumma kana minal-ladhina amanu wa tawasaw bis-sabri wa tawasaw bil-marhamah", "And then being among those who believed and advised one another to patience and advised one another to compassion.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(90, "Al-Balad", 18, "أُولَٰئِكَ أَصْحَابُ الْمَيْمَنَةِ", "أُو<madd>لَٰئِكَ</madd> أَ<tafkhim>صْحَابُ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>مَيْمَنَةِ", "Ula'ika ashabul-maymanah", "Those are the companions of the right.", listOf(TajweedRuleType.MADD, TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(90, "Al-Balad", 19, "وَالَّذِينَ كَفَرُوا بِآيَاتِنَا هُمْ أَصْحَابُ الْمَشْأَمَةِ", "وَ<hamzat_wasl>الَّذِينَ</hamzat_wasl> كَفَرُوا بِ<madd>آيَاتِنَا</madd> هُمْ أَ<tafkhim>صْحَابُ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>مَشْأَمَةِ", "Walladhina kafaru bi-ayatina hum ashabul-mash'amah", "But they who disbelieved in Our signs - they are the companions of the left.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.TAFKHIM)),
            make(90, "Al-Balad", 20, "عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌ", "عَلَيْهِمْ نَارٌ <idgham>مُّؤْ</idgham><tafkhim>صَدَةٌ</tafkhim>", "'Alayhim narum mu'sadah", "Over them will be fire closed in.", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM)),

            // ==================== SURAH 91: ASH-SHAMS (15 Verses) ====================
            make(91, "Ash-Shams", 1, "وَالشَّمْسِ وَضُحَاهَا", "وَ<hamzat_wasl>ال</hamzat_wasl>شَّمْسِ وَ<tafkhim>ضُحَاهَا</tafkhim>", "Wash-shamsi wa duhaha", "By the sun and its brightness", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(91, "Ash-Shams", 2, "وَالْقَمَرِ إِذَا تَلَاهَا", "وَ<hamzat_wasl>الْ</hamzat_wasl><tafkhim>قَمَرِ</tafkhim> إِذَا تَلَاهَا", "Wal-qamari idha talaha", "And [by] the moon when it follows it", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(91, "Ash-Shams", 3, "وَالنَّهَارِ إِذَا جَلَّاهَا", "وَ<hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّهَارِ</ghunnah> إِذَا جَلَّاهَا", "Wan-nahari idha jallaha", "And [by] the day when it displays it", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(91, "Ash-Shams", 4, "وَاللَّيْلِ إِذَا يَغْشَاهَا", "وَ<hamzat_wasl>ال</hamzat_wasl>لَّيْلِ إِذَا يَغْشَاهَا", "Wal-layli idha yaghshaha", "And [by] the night when it covers it", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(91, "Ash-Shams", 5, "وَالسَّمَاءِ وَمَا بَنَاهَا", "وَ<hamzat_wasl>ال</hamzat_wasl><madd>سَّمَاءِ</madd> وَمَا بَنَاهَا", "Was-sama'i wa ma banaha", "And [by] the sky and He who constructed it", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD)),
            make(91, "Ash-Shams", 6, "وَالْأَرْضِ وَمَا طَحَاهَا", "وَ<hamzat_wasl>الْ</hamzat_wasl>أَرْضِ وَمَا <tafkhim>طَحَاهَا</tafkhim>", "Wal-ardi wa ma tahaha", "And [by] the earth and He who spread it", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(91, "Ash-Shams", 7, "وَنَفْسٍ وَمَا سَوَّاهَا", "وَنَفْسٍ <idgham>وَمَا</idgham> سَوَّاهَا", "Wa nafsiw wa ma sawwaha", "And [by] the soul and He who proportioned it", listOf(TajweedRuleType.IDGHAM)),
            make(91, "Ash-Shams", 8, "فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا", "فَأَلْهَمَهَا فُجُورَهَا وَ<tafkhim>تَ</tafkhim><qalqalah>قْ</qalqalah>وَاهَا", "Fa-alhamaha fujuraha wa taqwaha", "And inspired it [with discernment of] its wickedness and its righteousness,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(91, "Ash-Shams", 9, "قَدْ أَفْلَحَ مَن زَكَّاهَا", "<tafkhim><qalqalah>قَدْ</qalqalah></tafkhim> أَفْلَحَ مَن <ikhfa>زَكَّاهَا</ikhfa>", "Qad aflaha man zakkaha", "He has succeeded who purifies it,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.GHUNNAH)),
            make(91, "Ash-Shams", 10, "وَقَدْ خَابَ مَن دَسَّاهَا", "وَ<tafkhim><qalqalah>قَدْ</qalqalah></tafkhim> خَابَ مَن <ikhfa>دَسَّاهَا</ikhfa>", "Wa qad khaba man dassaha", "And he has failed who instills it [with corruption].", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.GHUNNAH)),
            make(91, "Ash-Shams", 11, "كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا", "كَذَّبَتْ ثَمُودُ بِ<tafkhim>طَغْوَاهَا</tafkhim>", "Kadhdhabat Thamudu bi-taghwaha", "Thamud denied [their prophet] by reason of their transgression,", listOf(TajweedRuleType.TAFKHIM)),
            make(91, "Ash-Shams", 12, "إِذِ انبَعَثَ أَشْقَاهَا", "إِذِ <iqlab>انبَعَثَ</iqlab> أَ<tafkhim>شْقَاهَا</tafkhim>", "Idhim-ba'atha ashqaha", "When the most wretched of them was sent forth.", listOf(TajweedRuleType.IQLAB, TajweedRuleType.TAFKHIM)),
            make(91, "Ash-Shams", 13, "فَقَالَ لَهُمْ رَسُولُ اللَّهِ نَاقَةَ اللَّهِ وَسُقْيَاهَا", "فَ<tafkhim>قَالَ</tafkhim> لَهُمْ رَسُولُ <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهِ</tafkhim> نَا<tafkhim>قَةَ</tafkhim> <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهِ</tafkhim> وَسُ<qalqalah>قْ</qalqalah>يَاهَا", "Faqala lahum rasulul-lahi naqatal-lahi wa suqyaha", "And the messenger of Allah [Salih] said to them, '[Do not harm] the she-camel of Allah or [prevent her from] her drink.'", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(91, "Ash-Shams", 14, "فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنبِهِمْ فَسَوَّاهَا", "فَكَذَّبُوهُ فَعَ<tafkhim>قَرُوهَا</tafkhim> فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم <ikhfa>بِ</ikhfa><iqlab>ذَنبِهِمْ</iqlab> فَسَوَّاهَا", "Fakadhdhabuhu fa'aqaruha fadamdama 'alayhim rabbuhum bidhambihim fasawwaha", "But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them].", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.GHUNNAH, TajweedRuleType.IQLAB)),
            make(91, "Ash-Shams", 15, "وَلَا يَخَافُ عُقْبَاهَا", "وَلَا يَخَافُ عُ<qalqalah>قْ</qalqalah>بَاهَا", "Wa la yakhafu 'uqbaha", "And He does not fear the consequence thereof.", listOf(TajweedRuleType.QALQALAH)),

            // ==================== SURAH 92: AL-LAYL (21 Verses) ====================
            make(92, "Al-Layl", 1, "وَاللَّيْلِ إِذَا يَغْشَىٰ", "وَ<hamzat_wasl>ال</hamzat_wasl>لَّيْلِ إِذَا يَغْشَىٰ", "Wal-layli idha yaghsha", "By the night when it covers", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(92, "Al-Layl", 2, "وَالنَّهَارِ إِذَا تَجَلَّىٰ", "وَ<hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّهَارِ</ghunnah> إِذَا تَجَلَّىٰ", "Wan-nahari idha tajalla", "And [by] the day when it appears", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(92, "Al-Layl", 3, "وَمَا خَلَقَ الذَّكَرَ وَالْأُنثَىٰ", "وَمَا خَلَ<tafkhim>قَ</tafkhim> <hamzat_wasl>ال</hamzat_wasl>ذَّكَرَ وَ<hamzat_wasl>الْ</hamzat_wasl>أُ<ikhfa>نثَىٰ</ikhfa>", "Wa ma khalaqadh-dhakara wal-untha", "And [by] He who created the male and female,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(92, "Al-Layl", 4, "إِنَّ سَعْيَكُمْ لَشَتَّىٰ", "<ghunnah>إِنَّ</ghunnah> سَعْيَكُمْ لَشَتَّىٰ", "Inna sa'yakum lashatta", "Indeed, your efforts are diverse.", listOf(TajweedRuleType.GHUNNAH)),
            make(92, "Al-Layl", 5, "فَأَمَّا مَنْ أَعْطَىٰ وَاتَّقَىٰ", "فَ<ghunnah>أَمَّا</ghunnah> مَنْ <madd>أَعْطَىٰ</madd> وَ<hamzat_wasl>ا</hamzat_wasl>تَّ<tafkhim>قَىٰ</tafkhim>", "Fa-amma man a'ta wattaqa", "As for he who gives and fears Allah", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(92, "Al-Layl", 6, "وَصَدَّقَ بِالْحُسْنَىٰ", "وَ<tafkhim>صَدَّقَ</tafkhim> بِ<hamzat_wasl>الْ</hamzat_wasl>حُسْنَىٰ", "Wa saddaqa bil-husna", "And believes in the best [reward],", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(92, "Al-Layl", 7, "فَسَنُيَسِّرُهُ لِلْيُسْرَىٰ", "فَسَنُيَسِّرُهُ لِلْيُسْرَىٰ", "Fasanuyassiruhu lil-yusra", "We will ease him toward ease.", emptyList()),
            make(92, "Al-Layl", 8, "وَأَمَّا مَن بَخِلَ وَاسْتَغْنَىٰ", "وَ<ghunnah>أَمَّا</ghunnah> مَن <iqlab>بَخِلَ</iqlab> وَ<hamzat_wasl>ا</hamzat_wasl>سْتَغْنَىٰ", "Wa amma mam bakhila wastaghna", "But as for he who withholds and considers himself free of need", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.IQLAB, TajweedRuleType.HAMZAT_WASL)),
            make(92, "Al-Layl", 9, "وَكَذَّبَ بِالْحُسْنَىٰ", "وَكَذَّبَ بِ<hamzat_wasl>الْ</hamzat_wasl>حُسْنَىٰ", "Wa kadhdhaba bil-husna", "And denies the best [reward],", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(92, "Al-Layl", 10, "فَسَنُيَسِّرُهُ لِلْعُسْرَىٰ", "فَسَنُيَسِّرُهُ لِلْعُسْرَىٰ", "Fasanuyassiruhu lil-'usra", "We will ease him toward difficulty.", emptyList()),
            make(92, "Al-Layl", 11, "وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تَرَدَّىٰ", "وَمَا يُغْنِي عَنْهُ مَالُهُ <madd>إِذَا</madd> تَرَدَّىٰ", "Wa ma yughni 'anhu maluhu idha taradda", "And what will his wealth avail him when he falls?", listOf(TajweedRuleType.MADD)),
            make(92, "Al-Layl", 12, "إِنَّ عَلَيْنَا لَلْهُدَىٰ", "<ghunnah>إِنَّ</ghunnah> عَلَيْنَا لَلْهُدَىٰ", "Inna 'alayna lal-huda", "Indeed, [incumbent] upon Us is guidance.", listOf(TajweedRuleType.GHUNNAH)),
            make(92, "Al-Layl", 13, "وَإِنَّ لَنَا لَلْآخِرَةَ وَالْأُولَىٰ", "وَ<ghunnah>إِنَّ</ghunnah> لَنَا لَلْ<madd>آخِرَةَ</madd> وَ<hamzat_wasl>الْ</hamzat_wasl>أُولَىٰ", "Wa inna lana lal-akhirata wal-ula", "And indeed, to Us belongs the Hereafter and the first [life].", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL)),
            make(92, "Al-Layl", 14, "فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ", "فَ<madd>أَن</madd><ikhfa>ذَرْتُكُمْ</ikhfa> نَارًا <ikhfa>تَلَظَّىٰ</ikhfa>", "Fa-andhartukum naran talazza", "So I have warned you of a Fire which is blazing.", listOf(TajweedRuleType.MADD, TajweedRuleType.GHUNNAH)),
            make(92, "Al-Layl", 15, "لَا يَصْلَاهَا إِلَّا الْأَشْقَى", "لَا <tafkhim>يَصْلَاهَا</tafkhim> إِلَّا <hamzat_wasl>الْ</hamzat_wasl>أَ<tafkhim>شْقَى</tafkhim>", "La yaslaha illal-ashqa", "None will [enter to] burn therein except the most wretched one.", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(92, "Al-Layl", 16, "الَّذِي كَذَّبَ وَتَوَلَّىٰ", "<hamzat_wasl>الَّذِي</hamzat_wasl> كَذَّبَ وَتَوَلَّىٰ", "Alladhi kadhdhaba wa tawalla", "Who had denied and turned away.", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(92, "Al-Layl", 17, "وَسَيُجَنَّبُهَا الْأَتْقَى", "وَسَيُ<ghunnah>جَنَّبُهَا</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>أَ<tafkhim>تْ</tafkhim><qalqalah>قَى</qalqalah>", "Wa sayujannabuhal-atqa", "But the righteous one will avoid it -", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(92, "Al-Layl", 18, "الَّذِي يُؤْتِي مَالَهُ يَتَزَكَّىٰ", "<hamzat_wasl>الَّذِي</hamzat_wasl> يُؤْتِي مَالَهُ يَتَزَكَّىٰ", "Alladhi yu'ti malahu yatazakka", "[He] who gives [from] his wealth to purify himself", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(92, "Al-Layl", 19, "وَمَا لِأَحَدٍ عِندَهُ مِن نِّعْمَةٍ تُجْزَىٰ", "وَمَا لِأَحَدٍ عِن<ikhfa>دَهُ</ikhfa> مِن <idgham>نِّعْمَةٍ</idgham> <ikhfa><qalqalah>تُجْ</qalqalah>زَىٰ</ikhfa>", "Wa ma li-ahadin 'indahu min ni'matin tujza", "And not [giving] for anyone who has [done him] a favor to be rewarded", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.IDGHAM, TajweedRuleType.QALQALAH)),
            make(92, "Al-Layl", 20, "إِلَّا ابْتِغَاءَ وَجْهِ رَبِّهِ الْأَعْلَىٰ", "إِلَّا <hamzat_wasl>ا</hamzat_wasl><qalqalah>بْتِغَاءَ</qalqalah> وَ<qalqalah>جْهِ</qalqalah> رَبِّهِ <hamzat_wasl>الْ</hamzat_wasl>أَعْلَىٰ", "Illabtigha'a wajhi rabbihil-a'la", "But only seeking the countenance of his Lord, Most High.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH, TajweedRuleType.MADD)),
            make(92, "Al-Layl", 21, "وَلَسَوْفَ يَرْضَىٰ", "وَلَسَوْفَ <tafkhim>يَرْضَىٰ</tafkhim>", "Wa lasawfa yarda", "And he is going to be satisfied.", listOf(TajweedRuleType.TAFKHIM)),

            // ==================== SURAH 93: AD-DUHAA (11 Verses) ====================
            make(93, "Ad-Duhaa", 1, "وَالDuhaa", "وَ<hamzat_wasl>ال</hamzat_wasl><tafkhim>ضُّحَىٰ</tafkhim>", "Wad-duha", "By the morning sunlight", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(93, "Ad-Duhaa", 2, "وَاللَّيْلِ إِذَا سَجَىٰ", "وَ<hamzat_wasl>ال</hamzat_wasl>لَّيْلِ إِذَا سَجَىٰ", "Wal-layli idha saja", "And by the night when it covers with darkness,", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(93, "Ad-Duhaa", 3, "مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ", "مَا وَدَّعَكَ رَبُّكَ وَمَا <tafkhim>قَلَىٰ</tafkhim>", "Ma wadda'aka rabbuka wa ma qala", "Your Lord has not taken leave of you, [O Muhammad], nor has He detested [you].", listOf(TajweedRuleType.TAFKHIM)),
            make(93, "Ad-Duhaa", 4, "وَلَلْآخِرَةُ خَيْرٌ لَّكَ مِنَ الْأُولَىٰ", "وَلَلْ<madd>آخِرَةُ</madd> خَيْرٌ <idgham>لَّكَ</idgham> مِنَ <hamzat_wasl>الْ</hamzat_wasl>أُولَىٰ", "Wa lal-akhiratu khayrul laka minal-ula", "And the Hereafter is better for you than the first [life].", listOf(TajweedRuleType.MADD, TajweedRuleType.IDGHAM, TajweedRuleType.HAMZAT_WASL)),
            make(93, "Ad-Duhaa", 5, "وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ", "وَلَسَوْفَ يُعْ<tafkhim>طِيكَ</tafkhim> رَبُّكَ فَتَرْ<tafkhim>ضَىٰ</tafkhim>", "Wa lasawfa yu'tika rabbuka fatarda", "And your Lord is going to give you, and you will be satisfied.", listOf(TajweedRuleType.TAFKHIM)),
            make(93, "Ad-Duhaa", 6, "أَلَمْ يَجِدْكَ يَتِيمًا فَآوَىٰ", "أَلَمْ <qalqalah>يَجِدْكَ</qalqalah> يَتِيمًا <madd>فَآوَىٰ</madd>", "Alam yajidka yatiman fa-awa", "Did He not find you an orphan and give [you] refuge?", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.MADD)),
            make(93, "Ad-Duhaa", 7, "وَوَجَدَكَ ضَالًّا فَهَدَىٰ", "وَوَجَدَكَ <madd>ضَالًّا</madd> <ikhfa>فَهَدَىٰ</ikhfa>", "Wa wajadaka daallan fahada", "And He found you lost and guided [you],", listOf(TajweedRuleType.MADD, TajweedRuleType.GHUNNAH)),
            make(93, "Ad-Duhaa", 8, "وَوَجَدَكَ عَائِلًا فَأَغْنَىٰ", "وَوَجَدَكَ <madd>عَائِلًا</madd> فَأَغْنَىٰ", "Wa wajadaka 'a'ilan fa-aghna", "And He found you poor and made [you] self-sufficient.", listOf(TajweedRuleType.MADD)),
            make(93, "Ad-Duhaa", 9, "فَأَمَّا الْيَتِيمَ فَلَا تَقْهَرْ", "فَ<ghunnah>أَمَّا</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>يَتِيمَ فَلَا <tafkhim>تَ</tafkhim><qalqalah>قْ</qalqalah>هَرْ", "Fa-ammal-yatima fala taqhar", "So as for the orphan, do not oppress [him].", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(93, "Ad-Duhaa", 10, "وَأَمَّا السَّائِلَ فَلَا تَنْهَرْ", "وَ<ghunnah>أَمَّا</ghunnah> <hamzat_wasl>ال</hamzat_wasl><madd>سَّائِلَ</madd> فَلَا تَنْهَرْ", "Wa ammas-sa'ila fala tanhar", "And as for the petitioner, do not repel [him].", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD)),
            make(93, "Ad-Duhaa", 11, "وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ", "وَ<ghunnah>أَمَّا</ghunnah> بِنِعْمَةِ رَبِّكَ فَحَدِّثْ", "Wa amma bini'mati rabbika fahaddith", "But as for the favor of your Lord, report [it].", listOf(TajweedRuleType.GHUNNAH)),

            // ==================== SURAH 94: ASH-SHARH (8 Verses) ====================
            make(94, "Ash-Sharh", 1, "أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ", "أَلَمْ نَشْرَحْ لَكَ <tafkhim>صَ</tafkhim><qalqalah>دْرَكَ</qalqalah>", "Alam nashrah laka sadrak", "Did We not expand for you, [O Muhammad], your breast?", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(94, "Ash-Sharh", 2, "وَوَضَعْنَا عَنكَ وِزْرَكَ", "وَ<tafkhim>وَضَعْنَا</tafkhim> عَن<ikhfa>كَ</ikhfa> وِزْرَكَ", "Wa wada'na 'anka wizrak", "And We removed from you your burden", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.GHUNNAH)),
            make(94, "Ash-Sharh", 3, "الَّذِي أَنقَضَ ظَهْرَكَ", "<hamzat_wasl>الَّذِي</hamzat_wasl> <madd>أَن</madd><ikhfa>قَضَ</ikhfa> <tafkhim>ظَهْرَكَ</tafkhim>", "Alladhi anqada zahrak", "Which had weighed upon your back", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(94, "Ash-Sharh", 4, "وَرَفَعْنَا لَكَ ذِكْرَكَ", "وَرَفَعْنَا لَكَ ذِكْرَكَ", "Wa rafa'na laka dhikrak", "And raised high for you your repute.", emptyList()),
            make(94, "Ash-Sharh", 5, "فَإِنَّ مَعَ الْعُسْرِ يُسْرًا", "فَ<ghunnah>إِنَّ</ghunnah> مَعَ <hamzat_wasl>الْ</hamzat_wasl>عُسْرِ يُسْرًا", "Fa-inna ma'al-'usri yusra", "For indeed, with hardship [will be] ease.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(94, "Ash-Sharh", 6, "إِنَّ مَعَ الْعُسْرِ يُسْرًا", "<ghunnah>إِنَّ</ghunnah> مَعَ <hamzat_wasl>الْ</hamzat_wasl>عُسْرِ يُسْرًا", "Inna ma'al-'usri yusra", "Indeed, with hardship [will be] ease.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(94, "Ash-Sharh", 7, "فَإِذَا فَرَغْتَ فَانصَبْ", "فَإِذَا فَرَغْتَ فَ<hamzat_wasl>ا</hamzat_wasl>ن<ikhfa><tafkhim>صَ</tafkhim></ikhfa><qalqalah>بْ</qalqalah>", "Fa-idha faraghta fansab", "So when you have finished [your duties], then stand up [for worship].", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(94, "Ash-Sharh", 8, "وَإِلَىٰ رَبِّكَ فَارْغَب", "وَإِلَىٰ رَبِّكَ فَ<hamzat_wasl>ا</hamzat_wasl>رْغَ<qalqalah>ب</qalqalah>", "Wa ila rabbika farghab", "And to your Lord direct [your] longing.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),

            // ==================== SURAH 95: AT-TIN (8 Verses) ====================
            make(95, "At-Tin", 1, "وَالتِّينِ وَالزَّيْتُونِ", "وَ<hamzat_wasl>ال</hamzat_wasl>تِّينِ وَ<hamzat_wasl>ال</hamzat_wasl>زَّيْتُونِ", "Wat-tini waz-zaytun", "By the fig and the olive", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(95, "At-Tin", 2, "وَطُورِ سِينِينَ", "وَ<tafkhim>طُورِ</tafkhim> سِينِينَ", "Wa turi sinin", "And [by] Mount Sinai", listOf(TajweedRuleType.TAFKHIM)),
            make(95, "At-Tin", 3, "وَهَٰذَا الْبَلَدِ الْأَمِينِ", "وَهَٰذَا <hamzat_wasl>الْ</hamzat_wasl>بَلَدِ <hamzat_wasl>الْ</hamzat_wasl>أَمِينِ", "Wa hadhal-baladil-amin", "And [by] this secure city [Makkah],", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(95, "At-Tin", 4, "لَقَدْ خَلَقْنَا الْإِنسَانَ فِي أَحْسَنِ تَقْوِيمٍ", "لَ<qalqalah>قَدْ</qalqalah> خَلَ<qalqalah>قْ</qalqalah>نَا <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانَ</ikhfa> فِي <madd>أَحْسَنِ</madd> <tafkhim>تَ</tafkhim><qalqalah>قْ</qalqalah>وِيمٍ", "Laqad khalaqnal-insana fi ahsani taqwim", "We have certainly created man in the best of stature;", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(95, "At-Tin", 5, "ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ", "<ghunnah>ثُمَّ</ghunnah> رَدَ<qalqalah>دْنَاهُ</qalqalah> أَسْفَلَ سَافِلِينَ", "Thumma radadnahu asfala safilin", "Then We return him to the lowest of the low,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(95, "At-Tin", 6, "إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ", "إِلَّا <hamzat_wasl>الَّذِينَ</hamzat_wasl> <madd>آمَنُوا</madd> وَعَمِلُوا <hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّالِحَاتِ</tafkhim> فَلَهُمْ أَ<qalqalah>جْرٌ</qalqalah> غَيْرُ مَمْنُونٍ", "Illal-ladhina amanu wa 'amilus-salihati falahum ajrun ghayru mamnun", "Except for those who believe and do righteous deeds, for they will have a reward uninterrupted.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(95, "At-Tin", 7, "فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ", "فَمَا يُكَذِّبُكَ بَعْدُ بِ<hamzat_wasl>ال</hamzat_wasl>دِّينِ", "Fama yukadhdhibuka ba'du bid-din", "So what yet causes you to deny the Recompense?", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(95, "At-Tin", 8, "أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ", "أَلَيْسَ <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> بِأَحْكَمِ <hamzat_wasl>الْ</hamzat_wasl>حَاكِمِينَ", "Alaysal-lahu bi-ahkamil-hakimin", "Is not Allah the most just of judges?", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),

            // ==================== SURAH 96: AL-'ALAQ (19 Verses) ====================
            make(96, "Al-'Alaq", 1, "اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ", "<hamzat_wasl>ا</hamzat_wasl><qalqalah>قْ</qalqalah>رَأْ بِ<hamzat_wasl>ا</hamzat_wasl>سْمِ رَبِّكَ <hamzat_wasl>الَّذِي</hamzat_wasl> خَلَ<qalqalah>قَ</qalqalah>", "Iqra' bismi rabbikal-ladhi khalaq", "Recite in the name of your Lord who created -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(96, "Al-'Alaq", 2, "خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ", "خَلَ<qalqalah>قَ</qalqalah> <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانَ</ikhfa> مِنْ عَلَ<qalqalah>قٍ</qalqalah>", "Khalaqal-insana min 'alaq", "Created man from a clinging substance.", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(96, "Al-'Alaq", 3, "اقْرَأْ وَرَبُّكَ الْأَكْرَمُ", "<hamzat_wasl>ا</hamzat_wasl><qalqalah>قْ</qalqalah>رَأْ وَرَبُّكَ <hamzat_wasl>الْ</hamzat_wasl>أَكْرَمُ", "Iqra' wa rabbukal-akram", "Recite, and your Lord is the most Generous -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(96, "Al-'Alaq", 4, "الَّذِي عَلَّمَ بِالْقَلَمِ", "<hamzat_wasl>الَّذِي</hamzat_wasl> عَلَّمَ بِ<hamzat_wasl>الْ</hamzat_wasl><tafkhim>قَلَمِ</tafkhim>", "Alladhi 'allama bil-qalam", "Who taught by the pen -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(96, "Al-'Alaq", 5, "عَلَّمَ الْإِنسَانَ مَا لَمْ يَعْلَمْ", "عَلَّمَ <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانَ</ikhfa> مَا لَمْ يَعْلَمْ", "'Allamal-insana ma lam ya'lam", "Taught man that which he knew not.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(96, "Al-'Alaq", 6, "كَلَّا إِنَّ الْإِنسَانَ لَيَطْغَىٰ", "كَلَّا <ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانَ</ikhfa> لَيَ<tafkhim>طْ</tafkhim><qalqalah>غَىٰ</qalqalah>", "Kalla innal-insana layatgha", "No! [But] indeed, man transgresses", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(96, "Al-'Alaq", 7, "أَن رَّآهُ اسْتَغْنَىٰ", "أَن <idgham>رَّآهُ</idgham> <hamzat_wasl>ا</hamzat_wasl>سْتَغْنَىٰ", "Ar ra'ahustaghna", "Because he sees himself self-sufficient.", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL)),
            make(96, "Al-'Alaq", 8, "إِنَّ إِلَىٰ رَبِّكَ الرُّجْعَىٰ", "<ghunnah>إِنَّ</ghunnah> إِلَىٰ رَبِّكَ <hamzat_wasl>ال</hamzat_wasl>رُّ<qalqalah>جْعَىٰ</qalqalah>", "Inna ila rabbikar-ruj'a", "Indeed, to your Lord is the return.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(96, "Al-'Alaq", 9, "أَرَأَيْتَ الَّذِي يَنْهَىٰ", "أَرَأَيْتَ <hamzat_wasl>الَّذِي</hamzat_wasl> يَنْهَىٰ", "Ara'aytal-ladhi yanha", "Have you seen the one who forbids", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(96, "Al-'Alaq", 10, "عَبْدًا إِذَا صَلَّىٰ", "عَ<qalqalah>بْ</qalqalah>دًا إِذَا <tafkhim>صَلَّىٰ</tafkhim>", "'Abdan idha salla", "A servant when he prays?", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.TAFKHIM)),
            make(96, "Al-'Alaq", 11, "أَرَأَيْتَ إِن كَانَ عَلَى الْهُدَىٰ", "أَرَأَيْتَ إِن <ikhfa>كَانَ</ikhfa> عَلَى <hamzat_wasl>الْ</hamzat_wasl>هُدَىٰ", "Ara'ayta in kana 'alal-huda", "Have you seen if he is upon guidance", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(96, "Al-'Alaq", 12, "أَوْ أَمَرَ بِالتَّقْوَىٰ", "أَوْ أَمَرَ بِ<hamzat_wasl>ال</hamzat_wasl>تَّ<tafkhim>قْ</tafkhim><qalqalah>وَىٰ</qalqalah>", "Aw amara bit-taqwa", "Or enjoins righteousness?", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(96, "Al-'Alaq", 13, "أَرَأَيْتَ إِن كَذَّبَ وَتَوَلَّىٰ", "أَرَأَيْتَ إِن <ikhfa>كَذَّبَ</ikhfa> وَتَوَلَّىٰ", "Ara'ayta in kadhdhaba wa tawalla", "Have you seen if he denies and turns away -", listOf(TajweedRuleType.GHUNNAH)),
            make(96, "Al-'Alaq", 14, "أَلَمْ يَعْلَم بِأَنَّ اللَّهَ يَرَىٰ", "أَلَمْ يَعْلَم <ikhfa>بِ</ikhfa><ghunnah>أَنَّ</ghunnah> <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهَ</tafkhim> يَرَىٰ", "Alam ya'lam bi-annal-laha yara", "Does he not know that Allah sees?", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(96, "Al-'Alaq", 15, "كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًا بِالنَّاصِيَةِ", "كَلَّا لَئِن <idgham>لَّمْ</idgham> يَن<ikhfa>تَهِ</ikhfa> لَنَسْفَعًا <iqlab>بِ</iqlab><hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّاصِيَةِ</ghunnah>", "Kalla la'il lam yantahi lanasfa'am bin-nasiyah", "No! If he does not desist, We will surely drag him by the forelock -", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.GHUNNAH, TajweedRuleType.IQLAB, TajweedRuleType.HAMZAT_WASL)),
            make(96, "Al-'Alaq", 16, "نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ", "نَاصِيَةٍ <ikhfa>كَاذِبَةٍ</ikhfa> خَاطِئَةٍ", "Nasiyatin kadhibatin khati'ah", "A lying, sinning forelock.", listOf(TajweedRuleType.GHUNNAH)),
            make(96, "Al-'Alaq", 17, "فَلْيَدْعُ نَادِيَهُ", "فَلْ<qalqalah>يَدْعُ</qalqalah> نَادِيَهُ", "Falyad'u nadiyah", "Then let him call his associates;", listOf(TajweedRuleType.QALQALAH)),
            make(96, "Al-'Alaq", 18, "سَنَدْعُ الزَّبَانِيَةَ", "سَنَ<qalqalah>دْعُ</qalqalah> <hamzat_wasl>ال</hamzat_wasl>زَّبَانِيَةَ", "Sanad'uz-zabaniyah", "We will call the angels of Hell.", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL)),
            make(96, "Al-'Alaq", 19, "كَلَّا لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِب ۩", "كَلَّا لَا تُ<tafkhim>طِعْهُ</tafkhim> وَ<hamzat_wasl>ا</hamzat_wasl>سْ<qalqalah>جُدْ</qalqalah> وَ<hamzat_wasl>ا</hamzat_wasl><tafkhim>قْ</tafkhim><qalqalah>تَرِبْ</qalqalah> ۩", "Kalla la tuti'hu wasjud waqtarib", "No! Do not obey him. But prostrate and draw near [to Allah]. [Sajdah]", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH))
